starter.variables.tf:
variable "project_name" {
  description = "Prefix for generated resource names."
  type        = string
  default     = "arena"
}

variable "environments" {
  description = "Environments that need storage."
  type        = list(string)
  default     = ["dev", "prod"]
}

starter.main.tf:
locals {
  # TODO - Build the module input map.
  # Turn the environment list into a map of stable bucket names.
}

module "storage" {
  source      = "./modules/storage"
  for_each    = local.environment_map
  bucket_name = each.value
}

output "bucket_names" {
  value = { for env, bucket in module.storage : env => bucket.bucket_name }
}

starter.modules/storage/main.tf:
variable "bucket_name" {
  type = string
}

resource "terraform_data" "storage" {
  input = var.bucket_name
}

output "bucket_name" {
  value = var.bucket_name
}
